<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3'
import { appUrl } from '@/lib/url'
import ClinicLayout from '@/Layouts/ClinicLayout.vue'
import OdontogramChart from '@/Components/Odontogram/OdontogramChart.vue'
import { Activity, AlertTriangle, Calendar, CheckCircle2, ClipboardList, CreditCard, DollarSign, Download, Eye, FileHeart, FileText, FolderOpen, HeartPulse, Mail, Pencil, Phone, Plus, ReceiptText, ShieldAlert, Stethoscope, Upload } from 'lucide-vue-next'
import { computed, ref } from 'vue'

interface Professional { full_name: string }
interface Appointment { id: string; branch_id: string; start_time: string; end_time: string; status: string; reason: string | null; professional?: Professional; appointment_type?: { name: string } }
interface Encounter { id: string; encounter_date: string; status: string; chief_complaint: string | null; vital_signs: Record<string, string | number> | null; professional?: Professional; evolution?: { subjective: string | null; objective: string | null; assessment: string | null; plan: string | null; treatment_performed: string | null }; diagnoses: Array<{ id: string; code: string; description: string }>; amendments: Array<{ id: string }> }
interface TreatmentItem { id: string; tooth_number: number | null; phase: number; price: number; status: string; procedure?: { name: string } }
interface TreatmentPlan { id: string; title: string; status: string; total_estimated: number; progress_percentage: number; items: TreatmentItem[] }
interface Quote { id: string; quote_number: string; alternative_name: string; status: string; grand_total: number; expires_at: string | null }
interface Charge { id: string; charge_number: string; concept: string; total_amount: number; paid_amount: number; balance_due: number; status: string; due_date: string | null }
interface Payment { id: string; payment_number: string; total_amount: number; status: string; paid_at: string }
interface PatientFile { id: string; category: string; original_name: string; mime_type: string; size_bytes: number; notes: string | null; tooth_number: number | null; created_at: string }
interface Consent { id: string; title: string; signed_by_name: string; signed_at: string }
interface OdontogramEntry { id: string; tooth_number: number; surface: string; condition: string; lifecycle_state: string }

interface PatientDetails {
    id: string; record_number: string; first_name: string; last_name: string; full_name: string; identification_number: string | null
    age: number | null; gender: string | null; phone: string | null; email: string | null; address: string | null; blood_type: string | null; status: string
    emergency_contact_name: string | null; emergency_contact_phone: string | null
    medical_history: { allergies: string[] | null; systemic_conditions: string[] | null; current_medications: string[] | null; is_pregnant: boolean; has_pacemaker: boolean; bleeding_disorders: boolean; medical_notes: string | null } | null
    files: PatientFile[]; appointments: Appointment[]; clinical_encounters: Encounter[]; treatment_plans: TreatmentPlan[]; quotes: Quote[]; charges: Charge[]; payments: Payment[]; consents: Consent[]
    odontograms: Array<{ id: string; type: string; entries: OdontogramEntry[] }>
}

const props = defineProps<{ patient: PatientDetails; summary: { balance_due: number; next_appointment: Appointment | null; active_treatment_plan: TreatmentPlan | null; latest_encounter: Encounter | null } }>()
const activeTab = ref<'summary' | 'history' | 'odontogram' | 'appointments' | 'treatments' | 'quotes' | 'payments' | 'files'>('summary')
const fileForm = useForm({ file: null as File | null, category: 'document', tooth_number: null as number | null, notes: '' })
const tabs = [
    { id: 'summary', label: 'Resumen', icon: Activity }, { id: 'history', label: 'Historia clínica', icon: FileHeart }, { id: 'odontogram', label: 'Odontograma', icon: Stethoscope },
    { id: 'appointments', label: 'Citas', icon: Calendar }, { id: 'treatments', label: 'Tratamientos', icon: ClipboardList }, { id: 'quotes', label: 'Presupuestos', icon: ReceiptText },
    { id: 'payments', label: 'Pagos', icon: CreditCard }, { id: 'files', label: 'Documentos', icon: FolderOpen },
] as const
const teeth = [18,17,16,15,14,13,12,11,21,22,23,24,25,26,27,28,48,47,46,45,44,43,42,41,31,32,33,34,35,36,37,38]
const latestOdontogram = computed(() => props.patient.odontograms[0] || null)
const odontogramMatrix = computed(() => {
    const m: Record<number, any> = {}
    if (!latestOdontogram.value) return m
    for (const tooth of teeth) {
        const entries = latestOdontogram.value.entries.filter((e) => e.tooth_number === tooth)
        if (!entries.length) continue
        m[tooth] = { tooth_number: tooth, conditions: entries.map((e) => ({ id: e.id, condition: e.condition, surface: e.surface, lifecycle_state: e.lifecycle_state, recorded_at: '', notes: null })), surfaces: {}, latest_state: entries[entries.length - 1].lifecycle_state }
    }
    return m
})
const medicalAlerts = computed(() => [
    ...(props.patient.medical_history?.allergies || []).map((value) => ({ title: `Alergia a ${value}`, detail: 'Precaución farmacológica registrada', critical: true })),
    ...(props.patient.medical_history?.systemic_conditions || []).map((value) => ({ title: value, detail: 'Condición sistémica activa', critical: false })),
])
const latestVitals = computed(() => props.summary.latest_encounter?.vital_signs || null)

function formatMoney(value: number | string | null) { return new Intl.NumberFormat('es-DO', { style: 'currency', currency: 'DOP' }).format(Number(value || 0)) }
function formatDate(value: string | null, includeTime = false) { if (!value) return '—'; return new Intl.DateTimeFormat('es-DO', includeTime ? { dateStyle: 'medium', timeStyle: 'short' } : { dateStyle: 'medium' }).format(new Date(value)) }
function toothEntry(tooth: number) { return latestOdontogram.value?.entries.find((entry) => entry.tooth_number === tooth && entry.lifecycle_state === 'active') }
function toothClass(tooth: number) { const condition = toothEntry(tooth)?.condition; if (condition === 'caries') return 'border-[#D92D20] bg-[#FEE4E2] text-[#912018]'; if (condition === 'restoration' || condition === 'resin') return 'border-[#2458C6] bg-[#DDE7FF] text-[#163F91]'; if (condition === 'crown') return 'border-[#7A5AF8] bg-[#EEEAFF] text-[#5925DC]'; if (condition === 'implant') return 'border-[#007D73] bg-[#D8ECE9] text-[#005C55]'; if (condition === 'missing') return 'border-[#98A2B3] bg-[#EAECF0] text-[#667085] line-through'; return 'border-[#BDC9C6] bg-white text-[#455653]' }
function handleFile(event: Event) { const input = event.target as HTMLInputElement; fileForm.file = input.files?.[0] || null }
function uploadFile() { if (!fileForm.file) return; fileForm.post(appUrl(`/patients/${props.patient.id}/files`), { forceFormData: true, onSuccess: () => fileForm.reset() }) }
</script>

<template>
    <Head :title="`${patient.full_name} — Ficha 360`" />
    <ClinicLayout>
        <div class="-m-6 lg:-m-8">
            <section class="border-b border-[#BDC9C6] bg-[#FAF8FF] px-6 py-5 lg:px-8">
                <div class="flex flex-col gap-5 xl:flex-row xl:items-center xl:justify-between">
                    <div class="flex items-start gap-4">
                        <div class="grid h-16 w-16 shrink-0 place-items-center rounded-lg bg-[#2458C6] text-xl font-bold text-white">{{ patient.first_name[0] }}{{ patient.last_name[0] }}</div>
                        <div><div class="flex flex-wrap items-center gap-2"><h1 class="text-2xl font-bold text-[#131B2E]">{{ patient.full_name }}</h1><span class="bg-[#D8ECE9] px-2 py-1 text-xs font-bold text-[#006B63]">● Activo</span></div><div class="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-sm text-[#52615E]"><span class="font-mono"># {{ patient.record_number }}</span><span>• {{ patient.age ? `${patient.age} años` : 'Edad no registrada' }}</span><span v-if="patient.phone" class="inline-flex items-center gap-1"><Phone class="h-3.5 w-3.5" /> {{ patient.phone }}</span><span v-if="patient.email" class="inline-flex items-center gap-1"><Mail class="h-3.5 w-3.5" /> {{ patient.email }}</span></div></div>
                    </div>
                    <div class="flex flex-wrap gap-2"><Link :href="`/appointments?create=1&patient_id=${patient.id}`" class="inline-flex h-10 items-center gap-2 bg-[#005C55] px-4 text-sm font-semibold text-white"><Calendar class="h-4 w-4" /> Agendar cita</Link><Link :href="`/patients/${patient.id}/encounters/create`" class="inline-flex h-10 items-center gap-2 border border-[#9AAEAA] bg-white px-4 text-sm font-semibold text-[#005C55]"><FileHeart class="h-4 w-4" /> Nueva evolución</Link><Link :href="`/patients/${patient.id}/quotes/create`" class="inline-flex h-10 items-center gap-2 border border-[#9AAEAA] bg-white px-4 text-sm font-semibold text-[#005C55]"><FileText class="h-4 w-4" /> Presupuesto</Link><Link :href="`/patients/${patient.id}/billing`" class="inline-flex h-10 items-center gap-2 border border-[#9AAEAA] bg-white px-4 text-sm font-semibold text-[#005C55]"><DollarSign class="h-4 w-4" /> Cobro</Link><Link :href="`/patients/${patient.id}/edit`" class="inline-flex h-10 items-center gap-2 border border-[#9AAEAA] bg-white px-3 text-sm font-semibold text-[#344054]" aria-label="Editar paciente"><Pencil class="h-4 w-4" /> Editar</Link></div>
                </div>
            </section>

            <nav class="flex overflow-x-auto border-b border-[#BDC9C6] bg-[#FAF8FF] px-4 lg:px-8">
                <button v-for="tab in tabs" :key="tab.id" class="flex shrink-0 items-center gap-2 border-b-2 px-4 py-3 text-xs font-bold transition" :class="activeTab === tab.id ? 'border-[#007D73] text-[#006B63]' : 'border-transparent text-[#52615E] hover:text-[#131B2E]'" @click="activeTab = tab.id"><component :is="tab.icon" class="h-4 w-4" /> {{ tab.label }}</button>
            </nav>

            <div class="space-y-5 bg-[#F8FAFC] p-6 lg:p-8">
                <template v-if="activeTab === 'summary'">
                    <div class="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
                        <article class="border border-[#F5A3A0] bg-[#FFF9F8] p-4"><h2 class="flex items-center gap-2 text-lg font-semibold text-[#B42318]"><AlertTriangle class="h-5 w-5" /> Alertas clínicas</h2><div v-if="medicalAlerts.length" class="mt-4 space-y-2"><div v-for="alert in medicalAlerts" :key="alert.title" class="border p-3" :class="alert.critical ? 'border-[#F5A3A0] bg-white text-[#B42318]' : 'border-[#FEC84B] bg-[#FFFAEB] text-[#93370D]' "><p class="font-semibold">{{ alert.title }}</p><p class="mt-1 text-xs opacity-80">{{ alert.detail }}</p></div></div><p v-else class="mt-4 text-sm text-[#667085]">Sin alertas médicas activas.</p></article>
                        <article class="border border-[#BDC9C6] bg-[#FAF8FF] p-4"><h2 class="flex items-center justify-between text-lg font-semibold text-[#131B2E]"><span class="flex items-center gap-2"><Calendar class="h-5 w-5 text-[#007D73]" /> Próxima cita</span></h2><div v-if="summary.next_appointment" class="mt-4 border border-[#CDD5DF] bg-[#F0F2FF] p-4"><p class="font-mono text-lg font-bold text-[#131B2E]">{{ formatDate(summary.next_appointment.start_time, true) }}</p><p class="mt-2 text-sm text-[#344054]">{{ summary.next_appointment.professional?.full_name || 'Profesional por asignar' }}</p><p class="mt-1 text-sm text-[#52615E]">{{ summary.next_appointment.appointment_type?.name || summary.next_appointment.reason || 'Consulta clínica' }}</p></div><p v-else class="mt-4 text-sm text-[#667085]">No hay citas futuras programadas.</p></article>
                        <article class="border border-[#BDC9C6] bg-[#FAF8FF] p-4"><h2 class="flex items-center gap-2 text-lg font-semibold text-[#131B2E]"><HeartPulse class="h-5 w-5 text-[#B42318]" /> Últimos signos vitales</h2><dl v-if="latestVitals" class="mt-4 grid grid-cols-2 gap-2"><div v-for="vital in [{ label: 'Presión', value: latestVitals.blood_pressure, unit: 'mmHg' }, { label: 'Pulso', value: latestVitals.heart_rate, unit: 'lpm' }, { label: 'Temp.', value: latestVitals.temperature, unit: '°C' }, { label: 'SpO₂', value: latestVitals.oxygen_saturation, unit: '%' }]" :key="vital.label" class="border border-[#D8E0DE] bg-white p-2"><dt class="text-[10px] font-bold uppercase text-[#667085]">{{ vital.label }}</dt><dd class="mt-1 font-mono font-bold text-[#131B2E]">{{ vital.value || '—' }} <small v-if="vital.value" class="text-[9px] font-normal">{{ vital.unit }}</small></dd></div></dl><p v-else class="mt-4 text-sm text-[#667085]">Se registrarán en la próxima evolución clínica.</p><Link v-if="summary.latest_encounter" :href="`/encounters/${summary.latest_encounter.id}`" class="mt-3 block text-right text-xs font-bold text-[#006B63]">Ver evolución →</Link></article>
                        <article class="border border-[#BDC9C6] bg-[#FAF8FF] p-4"><h2 class="flex items-center gap-2 text-lg font-semibold text-[#131B2E]"><CreditCard class="h-5 w-5 text-[#455A73]" /> Saldo pendiente</h2><div class="py-6 text-center"><p class="text-xs font-semibold text-[#667085]">Total a pagar</p><p class="mt-2 font-mono text-3xl font-bold text-[#131B2E]">{{ formatMoney(summary.balance_due) }}</p></div><Link :href="`/patients/${patient.id}/billing`" class="flex h-10 items-center justify-center gap-2 border border-[#007D73] text-sm font-semibold text-[#006B63]"><DollarSign class="h-4 w-4" /> Registrar pago</Link></article>
                    </div>
                    <div class="grid gap-4 xl:grid-cols-[2fr_1fr]">
                        <article class="border border-[#BDC9C6] bg-[#FAF8FF] p-4"><div class="flex items-center justify-between"><h2 class="flex items-center gap-2 text-lg font-semibold text-[#131B2E]"><CheckCircle2 class="h-5 w-5 text-[#007D73]" /> Plan de tratamiento activo</h2><span v-if="summary.active_treatment_plan" class="bg-[#E5E9FF] px-2 py-1 text-xs font-semibold">{{ Math.round(summary.active_treatment_plan.progress_percentage) }}%</span></div><template v-if="summary.active_treatment_plan"><div class="mt-4 flex items-center justify-between gap-3"><p class="text-sm text-[#52615E]">{{ summary.active_treatment_plan.title }}</p><Link :href="`/treatment-plans/${summary.active_treatment_plan.id}`" class="shrink-0 text-xs font-bold text-[#006B63]">Abrir plan →</Link></div><div class="mt-2 h-2 overflow-hidden rounded-full bg-[#E5E9FF]"><div class="h-full bg-[#007D73]" :style="{ width: `${summary.active_treatment_plan.progress_percentage}%` }"></div></div><div class="mt-4 overflow-hidden border border-[#BDC9C6]"><div v-for="item in summary.active_treatment_plan.items.slice(0, 4)" :key="item.id" class="grid grid-cols-[1fr_100px_110px] border-b border-[#D8E0DE] px-3 py-2 text-sm last:border-0"><span>{{ item.procedure?.name || 'Procedimiento clínico' }}</span><span class="text-center font-mono">{{ item.tooth_number || '—' }}</span><span class="text-right font-semibold text-[#006B63]">{{ item.status }}</span></div></div></template><p v-else class="mt-4 text-sm text-[#667085]">Sin plan activo. Crea un presupuesto para iniciar el tratamiento.</p></article>
                        <article class="border border-[#BDC9C6] bg-[#FAF8FF] p-4"><h2 class="flex items-center gap-2 text-lg font-semibold text-[#131B2E]"><FileHeart class="h-5 w-5 text-[#455A73]" /> Última evolución</h2><div v-if="summary.latest_encounter" class="mt-4 border-l-4 border-[#A7B6C8] bg-white p-3"><p class="text-xs font-bold text-[#52615E]">{{ formatDate(summary.latest_encounter.encounter_date) }}</p><p class="mt-2 line-clamp-5 text-sm leading-5 text-[#263633]">{{ summary.latest_encounter.evolution?.treatment_performed || summary.latest_encounter.evolution?.assessment || summary.latest_encounter.chief_complaint || 'Evolución clínica registrada.' }}</p><p class="mt-3 text-xs font-semibold text-[#52615E]">{{ summary.latest_encounter.professional?.full_name }}</p></div><p v-else class="mt-4 text-sm text-[#667085]">Aún no hay evoluciones clínicas.</p><Link v-if="summary.latest_encounter" :href="`/encounters/${summary.latest_encounter.id}`" class="mt-3 block text-right text-xs font-bold text-[#006B63]">Abrir evolución completa →</Link></article>
                    </div>
                </template>

                <section v-else-if="activeTab === 'history'" class="space-y-4"><div class="flex items-center justify-between"><div><h2 class="text-xl font-bold text-[#131B2E]">Historia clínica y evoluciones</h2><p class="text-sm text-[#667085]">Registro cronológico SOAP e inmutable.</p></div><Link :href="`/patients/${patient.id}/encounters/create`" class="inline-flex h-10 items-center gap-2 bg-[#005C55] px-4 text-sm font-semibold text-white"><Plus class="h-4 w-4" /> Nueva evolución</Link></div><Link v-for="encounter in patient.clinical_encounters" :key="encounter.id" :href="`/encounters/${encounter.id}`" class="block border border-[#BDC9C6] bg-white p-5 transition hover:border-[#007D73]"><div class="flex flex-wrap items-start justify-between gap-2"><div><p class="font-mono text-xs font-bold text-[#006B63]">{{ formatDate(encounter.encounter_date, true) }}</p><h3 class="mt-1 font-semibold text-[#131B2E]">{{ encounter.chief_complaint || 'Atención odontológica' }}</h3><p class="text-xs text-[#667085]">{{ encounter.professional?.full_name }}</p></div><span class="bg-[#D8ECE9] px-2 py-1 text-xs font-semibold text-[#006B63]">{{ encounter.status }}</span></div><div class="mt-4 grid gap-3 md:grid-cols-2"><div v-for="field in [{ label: 'S', value: encounter.evolution?.subjective }, { label: 'O', value: encounter.evolution?.objective }, { label: 'A', value: encounter.evolution?.assessment }, { label: 'P', value: encounter.evolution?.plan }]" :key="field.label" class="border-l-2 border-[#9AAEAA] pl-3"><p class="text-xs font-bold text-[#006B63]">{{ field.label }}</p><p class="mt-1 text-sm text-[#455653]">{{ field.value || 'Sin registro' }}</p></div></div></Link><p v-if="!patient.clinical_encounters.length" class="border border-[#BDC9C6] bg-white p-10 text-center text-[#667085]">No hay evoluciones registradas.</p></section>

                <section v-else-if="activeTab === 'odontogram'" class="space-y-4"><div class="flex items-center justify-between"><div><h2 class="text-xl font-bold text-[#131B2E]">Odontograma FDI</h2><p class="text-sm text-[#667085]">Estado vigente de las 32 piezas permanentes.</p></div><Link :href="`/patients/${patient.id}/odontogram`" class="h-10 bg-[#005C55] px-4 py-2.5 text-sm font-semibold text-white">Abrir odontograma interactivo</Link></div><div class="border border-[#BDC9C6] bg-white p-6"><OdontogramChart :matrix="odontogramMatrix" dentition="permanent" /></div></section>

                <section v-else-if="activeTab === 'appointments'" class="space-y-4"><div class="flex items-end justify-between gap-3"><div><h2 class="text-xl font-bold text-[#131B2E]">Citas</h2><p class="text-sm text-[#667085]">Historial y próximos compromisos.</p></div><Link :href="`/appointments?create=1&patient_id=${patient.id}`" class="bg-[#005C55] px-4 py-2 text-sm font-semibold text-white">Nueva cita</Link></div><div class="overflow-hidden border border-[#BDC9C6] bg-white"><Link v-for="appointment in patient.appointments" :key="appointment.id" :href="`/appointments?date=${appointment.start_time.slice(0, 10)}&view=day&branch_id=${appointment.branch_id}&appointment_id=${appointment.id}`" class="grid gap-3 border-b border-[#D8E0DE] p-4 transition hover:bg-[#F7FAF9] md:grid-cols-[180px_1fr_180px_120px]"><span class="font-mono text-sm font-semibold">{{ formatDate(appointment.start_time, true) }}</span><div><p class="font-semibold text-[#131B2E]">{{ appointment.appointment_type?.name || appointment.reason || 'Consulta' }}</p><p class="text-xs text-[#667085]">{{ appointment.professional?.full_name }}</p></div><span class="text-sm text-[#52615E]">{{ appointment.reason }}</span><span class="text-xs font-bold text-[#006B63]">{{ appointment.status }}</span></Link></div></section>

                <section v-else-if="activeTab === 'treatments'" class="space-y-4"><h2 class="text-xl font-bold text-[#131B2E]">Planes de tratamiento</h2><Link v-for="plan in patient.treatment_plans" :key="plan.id" :href="`/treatment-plans/${plan.id}`" class="block border border-[#BDC9C6] bg-white p-5 transition hover:border-[#007D73]"><div class="flex justify-between"><div><h3 class="font-bold text-[#131B2E]">{{ plan.title }}</h3><p class="text-xs text-[#667085]">{{ plan.status }} · {{ plan.items.length }} procedimientos</p></div><p class="font-mono font-bold">{{ formatMoney(plan.total_estimated) }}</p></div><div class="mt-4 h-2 rounded-full bg-[#E5E9FF]"><div class="h-full rounded-full bg-[#007D73]" :style="{ width: `${plan.progress_percentage}%` }"></div></div></Link></section>

                <section v-else-if="activeTab === 'quotes'" class="space-y-4"><div class="flex justify-between"><h2 class="text-xl font-bold text-[#131B2E]">Presupuestos</h2><Link :href="`/patients/${patient.id}/quotes/create`" class="bg-[#005C55] px-4 py-2 text-sm font-semibold text-white">Nuevo presupuesto</Link></div><div class="overflow-hidden border border-[#BDC9C6] bg-white"><Link v-for="quote in patient.quotes" :key="quote.id" :href="`/quotes/${quote.id}`" class="grid gap-3 border-b border-[#D8E0DE] p-4 md:grid-cols-[140px_1fr_140px_120px]"><span class="font-mono font-bold text-[#006B63]">{{ quote.quote_number }}</span><span>{{ quote.alternative_name }}</span><span class="font-mono text-right">{{ formatMoney(quote.grand_total) }}</span><span class="text-right text-xs font-bold">{{ quote.status }}</span></Link></div></section>

                <section v-else-if="activeTab === 'payments'" class="grid gap-5 xl:grid-cols-2"><div><div class="mb-3 flex items-center justify-between"><h2 class="text-xl font-bold text-[#131B2E]">Cargos</h2><Link :href="`/patients/${patient.id}/billing`" class="text-sm font-bold text-[#006B63]">Abrir facturación →</Link></div><div class="border border-[#BDC9C6] bg-white"><Link v-for="charge in patient.charges" :key="charge.id" :href="`/charges/${charge.id}`" class="block border-b border-[#D8E0DE] p-4 transition hover:bg-[#F1FAF8]"><div class="flex justify-between"><p class="font-semibold">{{ charge.concept }}</p><p class="font-mono font-bold text-[#B42318]">{{ formatMoney(charge.balance_due) }}</p></div><p class="mt-1 text-xs text-[#667085]">{{ charge.charge_number }} · {{ charge.status }}</p><p class="mt-1 text-xs font-bold text-[#006B63]">Ver detalle →</p></Link></div></div><div><h2 class="mb-3 text-xl font-bold text-[#131B2E]">Pagos recibidos</h2><div class="border border-[#BDC9C6] bg-white"><Link v-for="payment in patient.payments" :key="payment.id" :href="`/payments/${payment.id}`" class="flex justify-between border-b border-[#D8E0DE] p-4 transition hover:bg-[#F1FAF8]"><div><p class="font-mono font-semibold text-[#006B63]">{{ payment.payment_number }}</p><p class="text-xs text-[#667085]">{{ formatDate(payment.paid_at, true) }}</p><p class="mt-1 text-xs font-bold text-[#006B63]">Ver recibo →</p></div><p class="font-mono font-bold">{{ formatMoney(payment.total_amount) }}</p></Link></div></div></section>

                <section v-else-if="activeTab === 'files'" class="space-y-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><h2 class="text-xl font-bold text-[#131B2E]">Documentos y consentimientos</h2><p class="text-sm text-[#667085]">Adjuntos clínicos privados y documentos firmados.</p></div><Link :href="`/patients/${patient.id}/consents`" class="inline-flex h-10 items-center gap-2 border border-[#007D73] px-4 text-sm font-semibold text-[#006B63]"><ShieldAlert class="h-4 w-4" /> Gestionar consentimientos</Link></div><form class="grid gap-3 border border-[#BDC9C6] bg-white p-4 md:grid-cols-[170px_150px_1fr_auto]" @submit.prevent="uploadFile"><select v-model="fileForm.category" class="h-10 border border-[#BDC9C6] px-3 text-sm"><option value="document">Documento</option><option value="radiography">Radiografía</option><option value="photo">Fotografía</option><option value="lab_result">Laboratorio</option><option value="consent">Consentimiento</option></select><select v-model="fileForm.tooth_number" class="h-10 border border-[#BDC9C6] px-3 text-sm"><option :value="null">Sin pieza</option><option v-for="tooth in teeth" :key="tooth" :value="tooth">Pieza {{ tooth }}</option></select><input type="file" required class="h-10 border border-[#BDC9C6] px-3 py-2 text-sm" @change="handleFile" /><button :disabled="fileForm.processing" class="inline-flex h-10 items-center gap-2 bg-[#005C55] px-4 text-sm font-semibold text-white"><Upload class="h-4 w-4" /> Adjuntar</button></form><div class="grid gap-3 md:grid-cols-2"><article v-for="file in patient.files" :key="file.id" class="flex items-center gap-3 border border-[#BDC9C6] bg-white p-4"><FileText class="h-7 w-7 shrink-0 text-[#007D73]" /><div class="min-w-0 flex-1"><p class="truncate font-semibold text-[#131B2E]">{{ file.original_name }}</p><p class="text-xs text-[#667085]">{{ file.category }} · {{ (file.size_bytes / 1024).toFixed(1) }} KB<span v-if="file.tooth_number"> · Pieza {{ file.tooth_number }}</span></p><p v-if="file.notes" class="mt-1 line-clamp-2 text-xs text-[#52615E]">{{ file.notes }}</p></div><div class="flex shrink-0 gap-1"><a v-if="file.mime_type === 'application/pdf' || file.mime_type.startsWith('image/')" :href="`/patient-files/${file.id}/view`" target="_blank" rel="noopener" class="grid h-9 w-9 place-items-center border border-[#9AAEAA] text-[#006B63]" aria-label="Ver archivo"><Eye class="h-4 w-4" /></a><a :href="`/patient-files/${file.id}/download`" class="grid h-9 w-9 place-items-center border border-[#9AAEAA] text-[#006B63]" aria-label="Descargar archivo"><Download class="h-4 w-4" /></a></div></article><Link v-for="consent in patient.consents" :key="consent.id" :href="`/patients/${patient.id}/consents?consent_id=${consent.id}`" class="flex items-center gap-3 border border-[#B7D9D4] bg-[#F1FAF8] p-4 transition hover:border-[#007D73]"><ShieldAlert class="h-7 w-7 shrink-0 text-[#007D73]" /><div><p class="font-semibold">{{ consent.title }}</p><p class="text-xs text-[#52615E]">Firmado por {{ consent.signed_by_name }} · {{ formatDate(consent.signed_at) }}</p><p class="mt-1 text-xs font-bold text-[#006B63]">Abrir documento sellado →</p></div></Link></div></section>
            </div>
        </div>
    </ClinicLayout>
</template>
